edits.newText:
def format_hunk(hunk) -> str:
    label = {"replace": "REPLACED", "delete": "DELETED", "insert": "INSERTED"}[hunk["tag"]]
    if hunk["tag"] == "replace":
        change = f"[{hunk['removed']} -> {hunk['added']}]"
    else:
        change = f"[{hunk['removed'] or hunk['added']}]"
    parts = ["..."]
    if hunk["before"]:
        parts.append(hunk["before"])
    parts.append(f"{label}: {change}")
    if hunk["after"]:
        parts.append(hunk["after"])
    parts.append("...")
    return " ".join(parts)
